import sys

mod = 998244353
facts = []
factInvs = []

def initialize():
    global facts, factInvs
    facts = [1] * 1000000
    factInvs = [1] * 1000000
    for i in range(1, len(facts)):
        facts[i] = multiplay(facts[i - 1], i)
    factInvs[-1] = fastPower(facts[-1], mod - 2)
    for i in range(len(factInvs) - 2, -1, -1):
        factInvs[i] = multiplay(factInvs[i + 1], i + 1)

def calculateCombination(n, k):
    return multiplay(facts[n], multiplay(factInvs[k], factInvs[n - k]))

def add(a, b):
    return (a + b) % mod

def subtract(a, b):
    return ((a - b) % mod + mod) % mod

def multiplay(a, b):
    return (a * b) % mod

def fastPower(base, exp):
    if exp == 0:
        return 1
    half = fastPower(base, exp // 2)
    if exp % 2 == 0:
        return multiplay(half, half)
    else:
        return multiplay(half, multiplay(half, base))

def powerCalculate(base, exp):
    result = 0
    for sub in range(base):
        delta = multiplay(fastPower(base - sub, exp), calculateCombination(base, sub))
        if sub % 2 == 0:
            result = add(result, delta)
        else:
            result = subtract(result, delta)
    return result

def main():
    initialize()
    input_data = sys.stdin.read().strip().split()
    n = int(input_data[0])
    k = int(input_data[1])
    if k == 0:
        print(facts[n])
        return
    if k >= n:
        print(0)
        return
    nUsable = n - k
    assignWays = powerCalculate(nUsable, n)
    pickThese = calculateCombination(n, nUsable)
    ways = multiplay(assignWays, pickThese)
    print(multiplay(ways, 2))

if __name__ == "__main__":
    main()

